async function searchEvidence(query,next=false){
  const selected=appState.selection;const epoch=next ? appState.evidenceEpoch : (appState.evidenceEpoch=(appState.evidenceEpoch || 0)+1);const list=$('evidence-events'),more=$('evidence-more');if(!list)return;if(more)more.disabled=true;
  if(!next){appState.evidenceQuery=query;appState.evidenceCursor=null;appState.evidencePlanId=null;list.replaceChildren(empty('Se caută în istoricul autorizat…','Evidence'));}
  try{
    const data=await api(devicePath('/evidence/search'),{method:'POST',body:JSON.stringify({query,limit:100,cursor:next ? appState.evidenceCursor : undefined,planId:next ? appState.evidencePlanId : undefined})});
    if(selected!==appState.selection || epoch!==appState.evidenceEpoch || list!==$('evidence-events'))return;
    if(next && appState.evidencePlanId && data.planId!==appState.evidencePlanId)throw new Error('Planul interogării s-a schimbat. Relansează întrebarea pentru un interval nou.');
    if(!next){appState.evidencePlanId=data.planId || null;list.replaceChildren();const context=node('div',undefined,'card-body muted small');context.append(node('div',formatEvidencePlanner(data.planner),'method-tag'),node('div',data.summary || 'Rezultate citate din evenimentele sincronizate.'));if(data.planner){const provenance=node('details');provenance.append(node('summary','Metadate de planificare'),node('pre',jsonText(data.planner)));context.append(provenance);}if(data.plan)context.append(node('div','Plan: '+data.mode+' · termen: '+(data.plan.literal || 'toate sursele')+' · '+(data.plan.from ? utcDate(Number(data.plan.from)) : 'începutul istoricului')+' → '+(data.plan.to ? utcDate(Number(data.plan.to)) : 'ultima observație')));if(data.periodCounts)context.append(node('div','Toată perioada interogată: '+JSON.stringify(data.periodCounts),'mono'));if(data.counts)context.append(node('div','Evenimente în această pagină: '+JSON.stringify(data.counts),'mono'));if(data.anchorCitation)context.append(button('Artefact de referință · event:'+data.anchorCitation.eventId,()=>showModal('Artefact de referință · eveniment original',data.anchorCitation)));if(data.currentState)context.append(button('Current state · cu referințe originale',()=>showModal('Current state · observațiile recente',data.currentState)));list.append(context);}
    for(const event of data.citations || [])list.append(eventRow(event));
    if(!data.citations?.length && !next)list.append(empty('Nu există observații potrivite în istoricul căutat. Aceasta nu dovedește absența activității.'));
    appState.evidenceCursor=data.coverage?.nextCursor || null;if(more){more.hidden=!appState.evidenceCursor;more.disabled=false;}
  }catch(error){if(selected===appState.selection && epoch===appState.evidenceEpoch)setError(error);if(more)more.disabled=false;}
}
