export function researchPage(env = {}) {
  const nonce = crypto.randomUUID().replaceAll("-", "");
  const config = { ...FIREBASE_WEB_CONFIG, ...(env.FIREBASE_WEB_API_KEY ? { apiKey: env.FIREBASE_WEB_API_KEY } : {}) };
  const html = RESEARCH_HTML.replaceAll("__NONCE__", nonce).replace("__FIREBASE_CONFIG__", JSON.stringify(config).replaceAll("<", "\\u003c"));
  return new Response(html, { headers: {
    "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "x-content-type-options": "nosniff",
    "referrer-policy": "no-referrer", "x-frame-options": "DENY",
    "content-security-policy": "default-src 'none'; script-src 'self' 'nonce-" + nonce + "'; style-src 'unsafe-inline'; connect-src 'self' https://identitytoolkit.googleapis.com https://securetoken.googleapis.com; img-src 'self' blob: data:; font-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",
    "permissions-policy": "camera=(), microphone=(), geolocation=()",
  } });
}
